def load_hypercache_engine(
    license_key: str = "HYPERCACHE-FREE-TRIAL-2026",
    recent_ratio: float = 0.08,
    sink_tokens: int = 14,
    block_size: int = 28,
):
    """
    Authenticates `license_key` and decrypts the corresponding HyperCache annual tier
    strictly in volatile RAM using AES-256-GCM.
    """
    decrypted = None
    for blob_str in (_VAULT_3_UNLIMITED_K8S, _VAULT_2_CLUSTER_PRO, _VAULT_1_DEV_PRO, _VAULT_0_TRIAL):
        try:
            envelope = base64.b85decode(blob_str.encode("ascii"))
            salt = envelope[:16]
            nonce = envelope[16:28]
            ciphertext = envelope[28:]

            kdf = PBKDF2HMAC(
                algorithm=hashes.SHA256(),
                length=32,
                salt=salt,
                iterations=600_000,
            )
            aes_key = kdf.derive(license_key.encode("utf-8"))
            aesgcm = AESGCM(aes_key)
            decrypted = aesgcm.decrypt(nonce, ciphertext, b"HYPERCACHE-4TIER-VAULT-V4")
            break
        except Exception:
            continue

    if decrypted is None:
        raise PermissionError(
            "[HyperCache License Error] Invalid or unrecognized License Key! "
            "Use 'HYPERCACHE-FREE-TRIAL-2026' for free evaluation or enter a valid Annual PRO Key."
        )

    raw_payload = zlib.decompress(decrypted)
    hdr_len = struct.unpack("<I", raw_payload[:4])[0]
    hdr_bytes = raw_payload[4 : 4 + hdr_len]
    bytecode_bytes = raw_payload[4 + hdr_len :]

    unpacked = struct.unpack("<11d5q", hdr_bytes)
    vault_floats = unpacked[:11]
    policy_ints = unpacked[11:]

    code_obj = marshal.loads(bytecode_bytes)
    mod_ns = {}
    exec(code_obj, mod_ns)
    engine_cls = mod_ns["_HyperCoreEngine"]
    return engine_cls(
        vault_floats,
        policy_ints,
        _lic_key_str=license_key,
        _r_win=recent_ratio,
        _s_tok=sink_tokens,
        _blk_sz=block_size,
    )